(2, 'GK1 WALK IN ', 'FB001', 'None', 'walk_in', 'draft', 'en', '[\"en\"]', 'one_question_per_page', 60, 'None', NULL, NULL, 1, NULL, 'simple_avg', 1, '2025-12-23 07:30:13', '2026-02-07 08:04:26', '{\"1\": [8, 10, 14], \"2\": [14], \"3\": [12, 13, 14], \"4\": [8], \"5\": [4, 3, 5, 6, 7, 8]}', 'Thank You', 'Thank you for your honest feedback.\r\nYour voice helps us strengthen our commitment to care, accuracy, and empathy.\r\nWe’re grateful you chose Dr Bhasin’s Lab and trusted us with your health.', NULL, NULL),
(3, 'OVERALL EXPERIENCE', 'CODE_1', 'None', 'walk_in', 'draft', 'en', '[\"en\"]', 'one_question_per_page', 60, 'OVERALL EXPERIENCE', NULL, NULL, 1, NULL, 'simple_avg', 1, '2026-01-13 12:22:13', '2026-01-21 11:36:05', '{\"1\": [26, 27], \"2\": [26, 27], \"3\": [22, 23, 24, 25], \"4\": [16, 18, 19, 20, 21], \"5\": [16, 18, 19, 20, 21]}', 'Thank You', 'Thank you for taking the time to share your experience with us.\r\nYour feedback truly matters and helps us care better for every patient we serve.\r\nWe appreciate the trust you’ve placed in Dr Bhasin’s Lab.', NULL, NULL),
(4, ' HOME SAMPLE COLLECTION – PATIENT FEEDBACK', 'CODE_2', 'None', 'walk_in', 'draft', 'en', '[\"en\"]', 'one_question_per_page', 60, 'Patient Feedback', NULL, NULL, 1, NULL, 'simple_avg', 1, '2026-01-13 13:02:10', '2026-02-11 11:30:04', '{\"1\": [37, 38, 39], \"2\": [37, 38, 39], \"3\": [34, 35, 36], \"4\": [29, 30, 31, 32, 33], \"5\": [29, 30, 31, 32, 33]}', 'Thank-You', 'Thank you for inviting us into your home and sharing your feedback.\r\nYour trust matters deeply to us, and your inputs help us improve how we care for you and other patients.', NULL, NULL),
(12, 'STAFF FEEDBACK QUESTIONNAIRE', 'CODE_5', 'None', 'walk_in', 'draft', 'en', '[\"en\"]', 'one_question_per_page', 180, 'Employee Feedback Form | कर्मचारी प्रतिक्रिया प्रपत्र', NULL, NULL, 1, NULL, 'simple_avg', 1, '2026-02-06 11:47:06', '2026-02-09 08:12:30', '{\"1\": [62, 63, 64, 65, 66, 67, 68, 69, 70, 71, 72, 73, 74, 75, 76, 77, 78], \"2\": [62, 63, 64, 65, 66, 67, 68, 69, 70, 71, 72, 73, 74, 75, 76, 77, 78], \"3\": [62, 63, 64, 65, 66, 67, 68, 69, 70, 71, 72, 73, 74, 75, 76, 77, 78], \"4\": [62, 63, 64, 65, 66, 67, 68, 69, 70, 71, 72, 73, 74, 75, 76, 77, 78]}', 'Thank You', 'Thank you for taking time to share your feedback. Your inputs will be reviewed carefully and used to improve systems, not to judge individuals. \r\nअपना फीडबैक देने के लिए धन्यवाद। आपकी राय का उपयोग व्यवस्था सुधारने के लिए किया जाएगा, किसी व्यक्ति का मूल्यांकन करने के लिए नहीं।    ', '/static/uploads/thankyou_40c9d513704f4a30a35d81fa73d94c75.png', '{\"mode\": \"allow\", \"values\": [\"1\"], \"question_order\": 16}');

