(61, 12, 6, ' How long have you been working with Dr Bhasin’s Lab? आप डॉ. भसीन लैब से कितने समय से जुड़े हुए हैं?            ', NULL, 'mcq_single', NULL, 1, 1, 1, 1, 0),
(62, 12, NULL, ' In One Sentence, What Does Doing Your Job Well Mean To You At Dr Bhasin’s Lab?  एक वाक्य में बताइए, डॉ. भसीन लैब में अपना काम अच्छे से करने का आपके लिए क्या अर्थ है?', NULL, 'text', 'Short answer | संक्षिप्त उत्तर', 1, 2, 1, 0, 0),
(63, 12, NULL, 'How Clear Are You About What Is Expected From You In Your Daily Work? आपको अपने रोज़ के काम में आपसे क्या अपेक्षा है, यह कितना स्पष्ट है?', NULL, 'mcq_single', NULL, 1, 3, 1, 0, 0),
(64, 12, NULL, ' What Usually Slows Down Your Work? (Select Up To Two) .  निम्न में से कौन-सी बातें आपके काम को सबसे ज़्यादा धीमा करती हैं? (अधिकतम 2 चुनें)', NULL, 'mcq_multi', NULL, 1, 4, 1, 0, 0),
(65, 12, NULL, ' When You Face A Work Problem, How Comfortable Are You Approaching Your Senior/Supervisor? काम से जुड़ी समस्या होने पर आप अपने सीनियर / सुपरवाइज़र से बात करने में कितना सहज महसूस करते हैं?', NULL, 'mcq_single', NULL, 1, 5, 1, 0, 0),
(66, 12, NULL, 'Do You Feel Your Hard Work And Professionalism Are Properly Recognised? क्या आपको लगता है कि आपकी मेहनत और प्रोफेशनल काम को उचित पहचान मिलती है?', NULL, 'mcq_single', NULL, 1, 6, 1, 0, 0),
(67, 12, NULL, 'What Makes You Continue Working At Dr Bhasin’s Lab? (Select Up To Two) डॉ. भसीन लैब में काम करते रहने का मुख्य कारण क्या है? (अधिकतम 2 चुनें)', NULL, 'mcq_multi', NULL, 1, 7, 1, 0, 0),
(68, 12, NULL, 'How Proud Do You Feel To Be Associated With Dr Bhasin’s Lab? डॉ. भसीन लैब से जुड़े होने पर आपको कितना गर्व महसूस होता है?', NULL, 'mcq_single', NULL, 1, 8, 1, 0, 0),
(69, 12, NULL, 'What One Change Would Help You Do Your Work Better? कौन-सा एक बदलाव आपके काम को बेहतर और आसान बना सकता है?', NULL, 'mcq_multi', NULL, 1, 9, 1, 0, 0),
(70, 12, NULL, ' Is There Anything You Want Leadership To Better Understand About Your Work Or Challenges? क्या आप चाहते हैं कि नेतृत्व (मैनेजमेंट) आपके काम या चुनौतियों को बेहतर समझे?', NULL, 'text', 'Short answer | संक्षिप्त उत्तर', 1, 10, 1, 0, 0),
(71, 12, NULL, ' How Fair Do You Feel Performance Evaluation And Recognition Are In The Organisation? आपके अनुसार काम का मूल्यांकन और पहचान कितनी निष्पक्ष (फेयर) है?', NULL, 'mcq_single', NULL, 1, 11, 1, 0, 0),
(72, 12, NULL, ' According To Employees, What Matters Most For Growth Or Recognition Here? (Select Two) आपके अनुसार यहाँ तरक्की या पहचान के लिए क्या सबसे अधिक मायने रखता है? (2 चुनें)', NULL, 'mcq_multi', NULL, 1, 12, 1, 0, 0),
(73, 12, NULL, ' How Comfortable Are You Raising Genuine Concerns With Your Immediate Senior? अपने सीनियर से वास्तविक समस्या साझा करने में आप कितना सहज हैं?', NULL, 'mcq_single', NULL, 1, 13, 1, 0, 0),
(74, 12, NULL, 'If Needed, Can You Reach Senior Leadership For Important Issues? जरूरत पड़ने पर क्या आप सीनियर मैनेजमेंट तक अपनी बात पहुँचा सकते हैं?', NULL, 'mcq_single', NULL, 1, 14, 1, 0, 0),
(75, 12, NULL, ' What Would Make Leadership More Accessible To You? (Select One) नेतृत्व को अधिक सुलभ (Accessible) बनाने के लिए क्या मदद करेगा?', NULL, 'mcq_multi', NULL, 1, 15, 1, 0, 0),
(76, 12, NULL, 'Do You Want To Raise Any Concern Or Complaint Now? क्या आप इस समय कोई समस्या या शिकायत दर्ज करना चाहते हैं?', NULL, 'mcq_single', NULL, 1, 16, 1, 0, 0),
(77, 12, NULL, 'What Type Of Issue Do You Want To Raise? आप किस प्रकार की समस्या बताना चाहते हैं?', NULL, 'mcq_multi', NULL, 1, 17, 1, 0, 0),
(78, 12, NULL, ' Details Of Your Concern कृपया अपनी समस्या का संक्षिप्त विवरण दें', NULL, 'text', 'Short description | संक्षिप्त विवरण', 1, 18, 1, 0, 0);

