(238, 19, 37, 'सिंपल 8:00 बजे तक ले गया था। मैंने ब्रेकफास्ट 8:15 तक कर लिया है। ब्लड शुगर पी पी 09:45 और 10:15 के बीच में लेना चाहिए। मैंने सैंपल कलेक्टिंग person को कांटेक्ट किया। पर उन्होंने बोला कोई और आदमी आएगा। \r\n\r\nजब सैंपल लेने के लिए needle अंदर लगाई थी तो उसने बहुत pain किया था इतना pain कभी नहीं हुआ और फिर भी ब्लड नहीं निकल रहा था। उसने needle को दाएं बाएं ऊपर नीचे सब तरफ घुमा दिया और ऐसा कभी नहीं हुआ और ना ही होना चाहिए। मुझे यह लगता है कि इस आदमी को पूरा अच्छा एक्सपीरियंस नहीं है।\r\nइससे पहले कभी ऐसा नहीं हुआ भसीन साहब।\r\nRegards\r\nK.L. BAJAJ', '[]', NULL, NULL, NULL, NULL, NULL),
